{
  "correction_rules": [
    "Adjust forecasts downward when sentiment history includes positive values (e.g., >0.00), as models tend to overreact to sentiment signals.",
    "Reduce forecast volatility in early periods (e.g., first 5 days) when historical price patterns show mean reversion toward prior 15-day average.",
    "When model forecasts spike above 65.00, apply a 5-10% downward correction to prevent overshoot, especially if sentiment is neutral or negative.",
    "If true outcome consistently exceeds forecast by >3.00, apply a lag correction: shift forecast 1-2 days ahead to align with observed price momentum.",
    "In periods with sustained upward trend (e.g., >3 consecutive days above 65.00), reduce forecast growth rate by 15-20% to avoid overestimating price peaks.",
    "When sentiment history shows no recent positive signals, increase forecast stability by averaging last 5 days’ true outcomes to reduce noise."
  ]
}
